Fixpoint popcount_nat (n : nat) : nat :=
  match n with
  | 0 => 0
  | S n' => (if Nat.odd n then 1 else 0) + popcount_nat n'
  end.

Definition chi_sign (chi dy : nat) : Z :=
  if Nat.eqb (Nat.modulo (popcount_nat (Nat.land chi dy)) 2) 0
  then 1%Z else (-1)%Z.

(* =============================================================================
   DDT construction -- uses sbox_val directly on nat input (no byte roundtrip)
   ============================================================================= *)

Fixpoint count_ddt (di d0 n : nat) : nat :=
  match n with
  | 0 => 0
  | S n' =>
    let x := n' in
    let x' := Nat.land (Nat.lxor x di) 255 in
    let s_x := sbox_val x in
    let s_x' := sbox_val x' in
    let diff := Nat.land (Nat.lxor s_x s_x') 255 in
    (if Nat.eqb diff d0 then 1 else 0) + count_ddt di d0 n'
  end.

Definition ddt_entry (di d0 : nat) : nat := count_ddt di d0 256.

(* =============================================================================
   Fourier coefficient computation -- exhaustive sum over 256x256 DDT entries
   ============================================================================= *)

Fixpoint fourier_sum_dx (chi dy n : nat) : Z :=
  match n with
  | 0 => 0%Z
  | S n' =>
    let dx := n' in
    let term := (Z.of_nat (ddt_entry dx dy)) * (chi_sign chi dy) in
    term + fourier_sum_dx chi dy n'
  end.

Fixpoint fourier_sum (chi n : nat) : Z :=
  match n with
  | 0 => 0%Z
  | S n' =>
    let dy := n' in
    fourier_sum_dx chi dy 256 + fourier_sum chi n'
  end.

Definition fourier_coeff_num (chi : nat) : Z := fourier_sum chi 256.

(* =============================================================================
   KEY LEMMA: F(chi={CHI}) = {COEFF} (nonzero!) -- disproves Fourier vanishing
   ============================================================================= *)

Lemma {LEMMA_NAME} : fourier_coeff_num {CHI} = {COEFF}%Z.
Proof.
  vm_compute. reflexivity.
Qed.

(* =============================================================================
   MAIN THEOREM: Camellia-s1 does NOT have Fourier vanishing
   ============================================================================= *)

Theorem camellia_no_fourier_vanishing :
  ~ (forall chi, chi > 0 -> chi < 256 -> fourier_coeff_num chi = 0%Z).
Proof.
  intro H.
  (* Witness: chi={CHI} gives nonzero coefficient *)
  assert (Hwit : fourier_coeff_num {CHI} = 0%Z) as -.
  {{ apply H. lia. }}
  rewrite <- {LEMMA_NAME}_ in Hwit.
  discriminate Hwit.
Qed.

